STREET_SUFFIX_CHOICES = [('', 'Select One'), ('none', 'None')] + [(v, v) for v in ('Avenue', 'Bend', 'Boulevard', 'Circle', 'Court', 'Cove', 'Drive', 'Highway', 'Lane', 'Loop', 'Parkway', 'Place', 'Road', 'Street', 'Terrace', 'Trail', 'Way')]

def compose_address(data):
    return ' '.join(str(data.get(name) or '').strip() for name in ('street_number', 'street_dir_prefix', 'street_name', 'street_suffix', 'street_dir_suffix') if data.get(name) and not (name == 'street_suffix' and data[name] == 'none'))
